<script setup lang="ts">import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import {Download,Check} from 'lucide-vue-next';import {useResearchData} from '../hooks/useResearch';import {useAuth} from '../stores/auth';import {useAction} from '../hooks/useAction';import {createNote,reviewNote} from '../api/notes';import {download} from '../api/client';import Notice from '../components/common/Notice.vue';import RunSummary from '../components/RunSummary.vue';import {ReviewStatus} from '../constants/enums';import {time} from '../utils/format';const s=useResearchData(),auth=useAuth(),a=useAction(),route=useRoute(),selected=ref(Number(route.query.run)||0),title=ref(''),interpretation=ref(''),recommendation=ref(''),reviews=ref<Record<number,string>>({});const runs=computed(()=>s.runs.filter(r=>r.status==='completed')),run=computed(()=>runs.value.find(r=>r.id===selected.value)||runs.value[0]),notes=computed(()=>s.notes.filter(n=>n.run_id===run.value?.id));function submit(){a.execute(async()=>{await createNote({run_id:run.value!.id,title:title.value,interpretation:interpretation.value,recommendation:recommendation.value});title.value='';interpretation.value='';recommendation.value='';await s.refresh()})}function review(id:number,status:string){a.execute(async()=>{await reviewNote(id,{status,review_note:reviews.value[id]});await s.refresh()})}function exportRun(id:number){a.execute(async()=>{await download(`/runs/${id}/export`,`survival-run-${id}.csv`)})}</script><template><div class="page"><div class="page-title"><div><p class="eyebrow">MAINTENANCE RECORD / 05</p><h1>维护建议<span>把证据与适用边界，一起交给负责人。</span></h1></div></div><Notice :message="s.error||a.error.value" @retry="s.refresh"/><label>关联研究<select aria-label="关联研究" :value="run?.id||''" @change="selected=Number(($event.target as HTMLSelectElement).value)"><option v-for="r in runs" :key="r.id" :value="r.id">#{{r.id}} / {{r.name}}</option></select></label><RunSummary v-if="run" :run="run"/><div class="notes-grid"><section><h2>提交维护观察建议</h2><form v-if="auth.user?.role!=='viewer'" @submit.prevent="submit"><label>建议标题<input aria-label="建议标题" v-model="title" minlength="2" required placeholder="例如：两批封装尾部观察补充"/></label><label>证据解释<textarea aria-label="证据解释" v-model="interpretation" minlength="8" required placeholder="结合删失、在险人数与区间，说明结果。"/></label><label>维护建议<textarea aria-label="维护建议" v-model="recommendation" minlength="8" required placeholder="记录现场复核与补充观察，不自动决定更换。"/></label><button class="primary" :disabled="a.busy.value||!run">提交负责人确认</button></form><p v-else class="role-note">阅读者可查看维护建议，获负责人确认后可导出研究CSV。</p></section><section class="note-list"><h2>确认档案</h2><article v-for="n in notes" :key="n.id"><div class="note-title"><span class="eyebrow">NOTE-{{n.id}} / RUN-{{n.run_id}}</span><span :class="['review-badge',n.status]">{{ReviewStatus[n.status as keyof typeof ReviewStatus]}}</span></div><h3>{{n.title}}</h3><p><b>证据</b>{{n.interpretation}}</p><p><b>建议</b>{{n.recommendation}}</p><small>{{n.owner}} · {{time(n.created_at)}}</small><div v-if="n.status==='submitted'&&auth.user?.role==='admin'" class="approval-form"><label>确认意见<textarea :aria-label="'确认意见 '+n.id" v-model="reviews[n.id]" minlength="8" placeholder="至少8字，写明适用范围和确认依据。"/></label><div><button class="primary" :disabled="a.busy.value||(reviews[n.id]||'').length<8" @click="review(n.id,'approved')"><Check :size="14"/>确认归档</button><button class="outline" :disabled="a.busy.value||(reviews[n.id]||'').length<8" @click="review(n.id,'rejected')">退回补充</button></div></div><div v-if="n.status!=='submitted'" class="review-note"><b>{{n.reviewer}}</b><p>{{n.review_note}}</p></div><button v-if="n.status==='approved'" class="text-link" @click="exportRun(n.run_id)"><Download :size="14"/>下载获批CSV</button></article><p v-if="!notes.length" class="empty">此研究还没有维护建议。研究员提交后由负责人确认，确认后开放导出。</p></section></div></div></template>
